#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n, t, k;
    scanf("%d %d %d", &n, &t, &k);
    vector<ll> a(n);
    for (auto &x : a) scanf("%lld", &x);
    // Max-heap by score, then smallest index; side 0 = front, 1 = back.
    auto cmp = [](const tuple<ll, int, int> &x, const tuple<ll, int, int> &y) {
        if (get<0>(x) != get<0>(y)) return get<0>(x) < get<0>(y);
        return get<1>(x) > get<1>(y);
    };
    priority_queue<tuple<ll, int, int>, vector<tuple<ll, int, int>>, decltype(cmp)> heap(cmp);
    int left = 0, right = n - 1;
    for (int i = 0; i < k && left <= right; i++, left++) heap.emplace(a[left], left, 0);
    for (int i = 0; i < k && left <= right; i++, right--) heap.emplace(a[right], right, 1);
    ll answer = 0;
    for (int i = 0; i < t; i++) {
        auto [v, idx, side] = heap.top();
        heap.pop();
        answer += v;
        if (left <= right) {
            if (side == 0) heap.emplace(a[left], left, 0), left++;
            else heap.emplace(a[right], right, 1), right--;
        }
    }
    printf("%lld\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), t = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Heap of indices: highest score first, then smallest index.
        PriorityQueue<Integer> heap = new PriorityQueue<>((x, y) -> a[x] != a[y] ? Long.compare(a[y], a[x]) : Integer.compare(x, y));
        int left = 0, right = n - 1;
        for (int i = 0; i < k && left <= right; i++) heap.add(left++);
        for (int i = 0; i < k && left <= right; i++) heap.add(right--);
        long answer = 0;
        for (int i = 0; i < t; i++) {
            int idx = heap.poll();
            answer += a[idx];
            if (left <= right) {
                // An index below left came from the front window, otherwise from the back.
                if (idx < left) heap.add(left++);
                else heap.add(right--);
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"container/heap"
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

var a []int64

// h holds indices: highest score first, then smallest index.
type h []int

func (x h) Len() int { return len(x) }
func (x h) Less(i, j int) bool {
	if a[x[i]] != a[x[j]] {
		return a[x[i]] > a[x[j]]
	}
	return x[i] < x[j]
}
func (x h) Swap(i, j int)       { x[i], x[j] = x[j], x[i] }
func (x *h) Push(v interface{}) { *x = append(*x, v.(int)) }
func (x *h) Pop() interface{} {
	old := *x
	v := old[len(old)-1]
	*x = old[:len(old)-1]
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, t, k := int(nextInt()), int(nextInt()), int(nextInt())
	a = make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	pq := &h{}
	left, right := 0, n-1
	for i := 0; i < k && left <= right; i++ {
		heap.Push(pq, left)
		left++
	}
	for i := 0; i < k && left <= right; i++ {
		heap.Push(pq, right)
		right--
	}
	var answer int64
	for i := 0; i < t; i++ {
		idx := heap.Pop(pq).(int)
		answer += a[idx]
		if left <= right {
			// An index below left came from the front window, otherwise from the back.
			if idx < left {
				heap.Push(pq, left)
				left++
			} else {
				heap.Push(pq, right)
				right--
			}
		}
	}
	fmt.Println(answer)
}
